public with sharing class ShipmentEventHandler {

    public static void handle(List<FB_Shipment_Event__e> events) {
        if (events == null || events.isEmpty()) {
            return;
        }

        // Map: upper-cased order number -> last event that references it.
        Map<String, FB_Shipment_Event__e> lastEventByOrder = new Map<String, FB_Shipment_Event__e>();

        for (FB_Shipment_Event__e e : events) {
            if (String.isBlank(e.Order_Number__c)) {
                continue;
            }
            String key = e.Order_Number__c.toUpperCase();
            lastEventByOrder.put(key, e);
        }

        if (lastEventByOrder.isEmpty()) {
            return;
        }

        // One SOQL query – skip Cancelled orders at the query level.
        List<FB_Sales_Order__c> orders = [
            SELECT Id, Order_Number__c, Status__c, Tracking_Number__c, Carrier__c
            FROM FB_Sales_Order__c
            WHERE Order_Number__c IN :lastEventByOrder.keySet()
              AND Status__c != 'Cancelled'
        ];

        if (orders.isEmpty()) {
            return;
        }

        // Index by upper-cased order number for O(1) lookup.
        Map<String, FB_Sales_Order__c> ordersByNumber = new Map<String, FB_Sales_Order__c>();
        for (FB_Sales_Order__c o : orders) {
            ordersByNumber.put(o.Order_Number__c.toUpperCase(), o);
        }

        List<FB_Sales_Order__c> toUpdate = new List<FB_Sales_Order__c>();
        Date today = Date.today();

        for (String orderNum : lastEventByOrder.keySet()) {
            FB_Sales_Order__c order = ordersByNumber.get(orderNum);
            if (order != null) {
                FB_Shipment_Event__e evt = lastEventByOrder.get(orderNum);
                order.Status__c          = 'Shipped';
                order.Tracking_Number__c = evt.Tracking_Number__c;
                order.Carrier__c         = evt.Carrier__c;
                order.Shipped_Date__c    = today;
                toUpdate.add(order);
            }
        }

        // One DML statement regardless of the number of events.
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
