```apex
/**
 * Maintains FB_Open_Pipeline__c (Currency) and FB_Open_Opportunities__c (Number)
 * on Account by recomputing them via SOQL whenever any opportunity under that
 * account is inserted, updated, deleted, or undeleted.
 *
 * Recursion guard: the existing AccountTrigger (after update) writes
 * FB_Account_Rating__c onto open opportunities, which re-fires this handler.
 * The static boolean short-circuits the nested call.  The pipeline fields
 * were already computed correctly in the first (outer) pass; the inner call
 * only touches FB_Account_Rating__c which is irrelevant to the pipeline math.
 */
public with sharing class OpportunityPipelineHandler {

    // ------------------------------------------------------------------
    //  Recursion guard
    // ------------------------------------------------------------------
    @TestVisible
    private static Boolean isRunning = false;

    // ------------------------------------------------------------------
    //  Public entry-points (one per DML operation)
    // ------------------------------------------------------------------

    public static void handleInsert() {
        if (isRunning) return;

        List<Opportunity> newRecords = (List<Opportunity>) Trigger.new;
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newRecords) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleUpdate() {
        if (isRunning) return;

        List<Opportunity> newRecords = (List<Opportunity>) Trigger.new;
        Map<Id, Opportunity> oldRecords = (Map<Id, Opportunity>) Trigger.oldMap;

        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newRecords) {
            Opportunity old = oldRecords.get(opp.Id);
            // Collect both new and old AccountId so moves are handled.
            // We always recalculate affected accounts regardless of which
            // field changed – the SOQL query inside recalculate determines
            // open/closed status via IsClosed, so no formula-field inspection
            // is needed here (formula fields are unavailable in trigger ctx).
            if (opp.AccountId != null) accountIds.add(opp.AccountId);
            if (old.AccountId != null) accountIds.add(old.AccountId);
        }
        recalculate(accountIds);
    }

    public static void handleDelete() {
        if (isRunning) return;

        List<Opportunity> oldRecords = (List<Opportunity>) Trigger.old;
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : oldRecords) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    public static void handleUndelete() {
        if (isRunning) return;

        List<Opportunity> newRecords = (List<Opportunity>) Trigger.new;
        Set<Id> accountIds = new Set<Id>();
        for (Opportunity opp : newRecords) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        }
        recalculate(accountIds);
    }

    // ------------------------------------------------------------------
    //  Core logic – single bulk SOQL + single bulk DML
    // ------------------------------------------------------------------

    private static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) return;

        isRunning = true;
        try {
            // Seed every affected account to 0 / 0 so accounts that end up
            // with zero open opportunities get explicit 0 values (not blank).
            Map<Id, Decimal> sumMap   = new Map<Id, Decimal>();
            Map<Id, Integer> countMap = new Map<Id, Integer>();

            for (Id accId : accountIds) {
                sumMap.put(accId,   0);
                countMap.put(accId, 0);
            }

            // One query, bulk-safe for 200+ records.
            // Null Amount is treated as 0 per the spec.
            for (Opportunity opp : [
                SELECT AccountId, Amount
                FROM   Opportunity
                WHERE  AccountId IN :accountIds
                   AND IsClosed = false
            ]) {
                Decimal amt = (opp.Amount == null) ? 0 : opp.Amount;
                sumMap.put(opp.AccountId,   sumMap.get(opp.AccountId)   + amt);
                countMap.put(opp.AccountId, countMap.get(opp.AccountId) + 1);
            }

            List<Account> accountsToUpdate = new List<Account>();
            for (Id accId : accountIds) {
                accountsToUpdate.add(new Account(
                    Id                        = accId,
                    FB_Open_Pipeline__c       = sumMap.get(accId),
                    FB_Open_Opportunities__c  = countMap.get(accId)
                ));
            }

            update accountsToUpdate;
        } finally {
            isRunning = false;
        }
    }
}
```

The error is that Salesforce does not allow inner (non-top-level) classes to implement `Database.Batchable<SObject>`. The fix is to make `LogPurgeJob` itself a **top-level** class that implements both `Schedulable` and `Database.Batchable<SObject>`, so the batch methods live directly on the outer class.

File: force-app/main/default/classes/LogPurgeJob.cls

```apex
public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<sObject> {

    public LogPurgeJob() {}

    // ---- Schedulable entry point ----
    public void execute(SchedulableContext sc) {
        Database.executeBatch(this, 200);
    }

    // ---- Batchable: start ----
    public Database.QueryLocator start(Database.BatchableContext bc) {
        DateTime thirtyDaysAgo = DateTime.now().addDays(-30);
        DateTime oneHundredEightyDaysAgo = DateTime.now().addDays(-180);

        return Database.getQueryLocator([
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE
                (CreatedDate < :thirtyDaysAgo AND (Level__c != 'ERROR' OR Level__c = null))
                OR
                (CreatedDate < :oneHundredEightyDaysAgo AND Level__c = 'ERROR')
        ]);
    }

    // ---- Batchable: execute ----
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        delete scope;
    }

    // ---- Batchable: finish ----
    public void finish(Database.BatchableContext bc) {}

    // ---- Static helper to schedule nightly at 02:00 ----
    public static Id scheduleNightly() {
        return System.schedule(
            'Log purge (nightly)',
            '0 0 2 * * ?',
            new LogPurgeJob()
        );
    }
}
```

**What changed and why:**

| Before | After | Reason |
|---|---|---|
| `LogPurgeJob` implements only `Schedulable`; an **inner** class `LogPurgeBatchable` implements `Database.Batchable<sObject>`. | `LogPurgeJob` itself implements **both** `Schedulable` and `Database.Batchable<sObject>` as a single top-level class. | Salesforce rejects inner/nested classes that implement `Database.Batchable`. Putting the batch methods on the top-level class satisfies the rule while keeping everything in the one required `.cls` file. |
| `execute(SchedulableContext)` calls `Database.executeBatch(new LogPurgeBatchable(), 200)` | `execute(SchedulableContext)` calls `Database.executeBatch(this, 200)` | Passes the same instance (which now implements both interfaces) to the batch engine. |

All other logic (30-day purge for non-ERROR, 180-day retention for ERROR, blank/null `Level__c` handling, cron `0 0 2 * * ?`, job name, return Id) is unchanged.

