    public void onAfterInsert() {
        Set<Id> qualifyingIds = new Set<Id>();
        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            if (opp.StageName == 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }
        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = 
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }

    public void onAfterUpdate() {
        Set<Id> qualifyingIds = new Set<Id>();
        Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>) Trigger.oldMap;

        for (Opportunity opp : (List<Opportunity>) Trigger.new) {
            // Qualifies only if the stage is changing to 'Closed Won' from something else
            if (opp.StageName == 'Closed Won' && oldMap.get(opp.Id).StageName != 'Closed Won') {
                qualifyingIds.add(opp.Id);
            }
        }

        if (!qualifyingIds.isEmpty()) {
            IOpportunityFulfilmentService service = 
                (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(qualifyingIds);
        }
    }
