public with sharing class Opportunities extends fflib_SObjectDomain {

    public Opportunities(List<SObject> records) {
        super(records);
    }

    public override void onValidate() {

        // Rule 1 – Amount must not be negative on insert or update
        if (Trigger.isBefore && (Trigger.isInsert || Trigger.isUpdate)) {
            for (SObject sobj : records) {
                Opportunity opp = (Opportunity) sobj;
                if (opp.Amount != null && opp.Amount < 0) {
                    error('Amount cannot be negative.', (SObject)opp, 'Amount');
                }
            }
        }

        // Rule 2 – On update, if the stage was already "Closed Won" before the
        //          update, Amount must not change.
        //          (Transitioning INTO Closed Won in the same update is allowed.)
        if (Trigger.isBefore && Trigger.isUpdate) {
            Map<Id, SObject> oldMap = (Map<Id, SObject>) Trigger.oldMap;
            for (SObject sobj : records) {
                Opportunity opp = (Opportunity) sobj;
                Opportunity oldOpp = (Opportunity) oldMap.get(opp.Id);
                if (oldOpp.StageName == 'Closed Won' && opp.Amount != oldOpp.Amount) {
                    error('Amount cannot change on a won opportunity.', (SObject)opp, 'Amount');
                }
            }
        }
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> sObjectList) {
            return new Opportunities(sObjectList);
        }
    }
}
