    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new List<Opportunity>();
        }

        fflib_QueryFactory qf = newQueryFactory();

        List<String> idStrings = new List<String>();
        for (Id accId : accountIds) {
            idStrings.add(accId);
        }

        qf.setCondition('AccountId IN (' + String.join(idStrings, ',') + ')');
        qf.setCondition('IsClosed = false');
        qf.addRelatedFields('Account', new List<Schema.SObjectField>{ Account.Name });
        qf.setOrdering(new List<String>{ 'Amount DESC NULLS LAST', 'CloseDate ASC' });
        qf.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(qf.toQueryString());
    }
}
