/**
 * @description Selector for Account records. Extends fflib_SObjectSelector and
 *              dynamically includes fields from the Credit_Review field set.
 *              Enforces user-mode security (FLS + sharing) via withUserMode().
 */
public inherited sharing class AccountsSelector extends fflib_SObjectSelector {

    public AccountsSelector() {
        withUserMode();
    }

    public Schema.SObjectType getSObjectType() {
        return Account.SObjectType;
    }

    /**
     * Returns Id, Name, Industry plus every field present in the
     * Credit_Review field set (admin-configurable, no code changes needed).
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        List<Schema.SObjectField> fields = new List<Schema.SObjectField>{
            Account.Id,
            Account.Name,
            Account.Industry
        };

        FieldSet creditReview = Account.SObjectType.getDescribe()
            .fieldSets.getMap().get('Credit_Review');

        if (creditReview != null) {
            Map<String, Schema.SObjectField> fieldMap =
                Account.SObjectType.getDescribe().fields.getMap();

            Set<String> existingNames = new Set<String>();
            for (Schema.SObjectField f : fields) {
                existingNames.add(f.getDescribe().getName().toLowerCase());
            }

            for (FieldSetTuple tuple : creditReview.fields) {
                String apiName = tuple.fieldPath;
                if (!existingNames.contains(apiName.toLowerCase())) {
                    Schema.SObjectField token = fieldMap.get(apiName);
                    if (token != null) {
                        fields.add(token);
                    }
                }
            }
        }

        return fields;
    }

    /**
     * Standard by-id selector. Uses fflib base query which honours
     * getSObjectFieldList() and the user-mode setting from the constructor.
     */
    public List<Account> selectById(Set<Id> accountIds) {
        return (List<Account>) selectSObjectsById(accountIds);
    }

    /**
     * Returns Accounts with their child Contacts in a single query.
     * The Contact sub-select is derived from ContactsSelector's field list.
     * Runs in user mode (WITH USER_MODE) so FLS and sharing are enforced.
     */
    public List<Account> selectByIdWithContacts(Set<Id> accountIds) {
        // Build Account field names
        List<String> accountFields = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            String qualified = field.getDescribe().getName();
            accountFields.add(qualified.substringAfter('.'));
        }

        // Build Contact sub-query fields from ContactsSelector
        ContactsSelector contactsSel = new ContactsSelector();
        List<String> contactFields = new List<String>();
        for (Schema.SObjectField field : contactsSel.getSObjectFieldList()) {
            String qualified = field.getDescribe().getName();
            contactFields.add(qualified.substringAfter('.'));
        }

        // Format account IDs for SOQL IN clause (no bind variables with Database.query(String))
        List<String> idStrings = new List<String>();
        for (Id acctId : accountIds) {
            idStrings.add(String.valueOf(acctId));
        }

        String soql = 'SELECT ' + String.join(accountFields, ', ') +
            ', (SELECT ' + String.join(contactFields, ', ') + ' FROM Contacts) ' +
            'FROM Account ' +
            'WHERE Id IN (' + String.join(idStrings, ',') + ') ' +
            'WITH USER_MODE';

        return Database.query(soql);
    }
}
