public with sharing class LineItemDiscountHandler {

    public void applyDefaultDiscounts(List<OpportunityLineItem> records) {
        // 1. Collect unique Product2Ids for lines that still need a discount
        Set<Id> productIdsNeedingDiscount = new Set<Id>();
        for (OpportunityLineItem oli : records) {
            if (oli.Discount == null && oli.Product2Id != null) {
                productIdsNeedingDiscount.add(oli.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        // 2. Single bulk-safe SOQL – one query regardless of line count
        Map<Id, Product2> productMap = new Map<Id, Product2>(
            [SELECT Id, Family FROM Product2 WHERE Id IN :productIdsNeedingDiscount]
        );

        // 3. Delegate the family→discount mapping to PricingRules (pure method, no SOQL)
        Map<Id, Decimal> discountByProductId = new Map<Id, Decimal>();
        for (Id prodId : productIdsNeedingDiscount) {
            Product2 p = productMap.get(prodId);
            if (p != null) {
                discountByProductId.put(
                    prodId,
                    PricingRules.standardDiscountForFamily(p.Family)
                );
            }
        }

        // 4. Apply the default discount only to lines where the rep left Discount null
        for (OpportunityLineItem oli : records) {
            if (oli.Discount == null) {
                Decimal stdDiscount = discountByProductId.get(oli.Product2Id);
                if (stdDiscount != null) {
                    oli.Discount = stdDiscount;
                }
            }
        }
    }
}
