import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import { updateRecord, refreshApex } from 'lightning/uiRecordApi';
import getContacts from '@salesforce/apex/ContactController.getContacts';

const COLUMNS = [
    { label: 'Name', fieldName: 'Name', type: 'text' },
    { label: 'Title', fieldName: 'Title', type: 'text', editable: true },
    { label: 'Phone', fieldName: 'Phone', type: 'phone', editable: true },
    { label: 'Email', fieldName: 'Email', type: 'email', editable: true }
];

export default class AccountContactsTable extends LightningElement {
    @api recordId;

    @track contacts = [];
    @track draftValues = [];

    wiredResult;

    columns = COLUMNS;

    @wire(getContacts, { accountId: '$recordId' })
    wiredContacts(result) {
        this.wiredResult = result;
        const { data, error } = result;
        if (data) {
            this.contacts = data;
        } else if (error) {
            console.error('Error loading contacts:', error);
        }
    }

    async handleSave(event) {
        const drafts = event.detail.draftValues;

        const promises = drafts.map((draft) =>
            updateRecord({
                fields: { ...draft }
            })
        );

        const results = await Promise.allSettled(promises);

        const failure = results.find((r) => r.status === 'rejected');

        if (failure) {
            this.dispatchEvent(
                new ShowToastEvent({
                    variant: 'error',
                    title: 'Could not save contacts',
                    message: failure.reason.body.message
                })
            );
            return;
        }

        this.draftValues = [];
        this.dispatchEvent(
            new ShowToastEvent({
                variant: 'success',
                title: 'Contacts updated'
            })
        );
        return refreshApex(this.wiredResult);
    }
}
