import { LightningElement, wire } from 'lwc';
import { MessageContext, subscribe, unsubscribe, publish, APPLICATION_SCOPE } from 'lightning/messageService';
import ACCOUNT_SELECTED from '@salesforce/messageChannel/Account_Selected__c';

export default class AccountDetailsPanel extends LightningElement {
    @wire(MessageContext)
    context;

    subscription = null;
    selectedRecordId = null;

    // ─── Lifecycle ────────────────────────────────────────────────────────────
    connectedCallback() {
        this.subscribeToChannel();
    }

    disconnectedCallback() {
        this.unsubscribeFromChannel();
    }

    renderedCallback() {
        // MessageContext may resolve after connectedCallback; attempt again.
        this.subscribeToChannel();
    }

    // ─── Pub/Sub helpers ──────────────────────────────────────────────────────
    subscribeToChannel() {
        if (this.subscription || !this.context) {
            return;
        }
        this.subscription = subscribe(
            this.context,
            ACCOUNT_SELECTED,
            (message) => this.handleMessage(message),
            { scope: APPLICATION_SCOPE }
        );
    }

    unsubscribeFromChannel() {
        if (this.subscription) {
            unsubscribe(this.subscription);
            this.subscription = null;
        }
    }

    // ─── Message handler ──────────────────────────────────────────────────────
    handleMessage(message) {
        if (message && message.recordId) {
            this.selectedRecordId = message.recordId;
        } else {
            this.selectedRecordId = null;
        }
    }

    // ─── Public actions ───────────────────────────────────────────────────────
    handleClear() {
        if (this.context) {
            publish(this.context, ACCOUNT_SELECTED, { recordId: null });
        }
    }

    // ─── Template getters ─────────────────────────────────────────────────────
    get isShowingForm() {
        return !!this.selectedRecordId;
    }
}
