import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    _heading;
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    // --- heading: store raw value, expose upper-case only for display ---
    @api
    get heading() {
        return this._heading;
    }
    set heading(value) {
        this._heading = value;
    }

    get displayHeading() {
        return this._heading ? this._heading.toUpperCase() : '';
    }

    // --- tasks: work on our own deep copies, react to parent changes ---
    @api
    get tasks() {
        return this._tasks;
    }
    set tasks(value) {
        this._tasks = value;
        this.items = value.map((t) => ({ ...t }));
    }

    // --- remaining count (re-computes whenever items array reference changes) ---
    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const id = event.target.dataset.id;
        this.items = this.items.map((t) =>
            t.id === id ? { ...t, done: !t.done } : t
        );
    }
}
