```apex
/**
 * GiftImportService
 *
 * Stages one NPSP Data Import record per WebGift, inserts them so that
 * NPSP's Bulk Data Importer (BDI) trigger handler processes them
 * synchronously in the same transaction, and returns per-gift results.
 *
 * The BDI honours the org's npsp__Data_Import_Settings__c for contact
 * matching (first name + last name + email) and donation matching (never
 * match existing donations), household creation, and donation processing.
 */
public class GiftImportService {

    // ─── Input / Output DTOs ────────────────────────────────────────────────

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;        // the donor's personal email
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;        // matched or newly created Contact
        public Id opportunityId;    // newly created Opportunity (donation)
        public String errorMessage; // NPSP failure detail when success == false
    }

    // ─── Constants ──────────────────────────────────────────────────────────

    private static final String STATUS_IMPORTED = 'Imported';
    private static final String DONOR_CONTACT1  = 'Contact1';

    // ─── Public entry point ─────────────────────────────────────────────────

    /**
     * importGifts – processes a list of WebGift records through NPSP BDI.
     *
     * @param gifts  the gifts to import (may be null or empty)
     * @return one ImportResult per gift, in the same order as the input
     */
    public static List<ImportResult> importGifts(List<WebGift> gifts) {

        // Null / empty guard
        if (gifts == null || gifts.isEmpty()) {
            return new List<ImportResult>();
        }

        // 1. Build one npsp__DataImport__c staging record per gift
        //    IMPORTANT: new List<SObject>(n) pre-fills with n nulls in Apex,
        //    so we must use an empty list and add elements.
        List<npsp__DataImport__c> diRecords = new List<npsp__DataImport__c>();

        for (WebGift gift : gifts) {
            npsp__DataImport__c di = new npsp__DataImport__c();
            di.npsp__Contact1_Firstname__c        = (gift != null) ? gift.firstName     : null;
            di.npsp__Contact1_Lastname__c         = (gift != null) ? gift.lastName      : null;
            di.npsp__Contact1_Personal_Email__c   = (gift != null) ? gift.email         : null;
            di.npsp__Donation_Amount__c           = (gift != null) ? gift.amount        : null;
            di.npsp__Donation_Date__c             = (gift != null) ? gift.giftDate      : null;
            di.npsp__Donation_Donor__c            = DONOR_CONTACT1;
            // Leave npsp__Status__c at its default ('New') so BDI picks it up
            diRecords.add(di);
        }

        // 2. Insert – the BDI trigger handler processes records synchronously
        //    in the after-insert context (same transaction), creating/
        //    matching Contacts, Households, and Opportunities per the org's
        //    npsp__Data_Import_Settings__c.
        //
        //    Using allOrNone = false so that a single staging-row DML failure
        //    does not abort the remaining rows.
        Database.SaveResult[] saveResults = Database.insert(diRecords, false);

        // 3. Collect IDs of rows that made it into the org
        List<Id> insertedIds = new List<Id>();
        for (Database.SaveResult sr : saveResults) {
            if (sr.isSuccess()) {
                insertedIds.add(sr.getId());
            }
        }

        // 4. Query back the BDI-processed data to read final status & refs
        //    After the trigger completes, npsp__Status__c is 'Imported' or
        //    'Failed'; lookups and failure info are populated.
        Map<Id, npsp__DataImport__c> processedMap = new Map<Id, npsp__DataImport__c>();

        if (!insertedIds.isEmpty()) {
            for (npsp__DataImport__c di : [
                SELECT Id,
                       npsp__Status__c,
                       npsp__Contact1Imported__c,
                       npsp__DonationImported__c,
                       npsp__FailureInformation__c
                  FROM npsp__DataImport__c
                 WHERE Id IN :insertedIds
            ]) {
                processedMap.put(di.Id, di);
            }
        }

        // 5. Assemble results in strict input order
        List<ImportResult> results = new List<ImportResult>();

        for (Integer i = 0; i < saveResults.size(); i++) {
            ImportResult ir = new ImportResult();
            Database.SaveResult sr = saveResults[i];

            if (!sr.isSuccess()) {
                // Staging-row insert failed (platform-level, not BDI)
                ir.success = false;
                ir.errorMessage = buildInsertErrorMessage(sr);
            } else {
                npsp__DataImport__c di = processedMap.get(sr.getId());

                if (di != null && di.npsp__Status__c == STATUS_IMPORTED) {
                    ir.success       = true;
                    ir.contactId     = di.npsp__Contact1Imported__c;
                    ir.opportunityId = di.npsp__DonationImported__c;
                } else {
                    ir.success = false;
                    if (di != null) {
                        ir.errorMessage = String.isNotBlank(di.npsp__FailureInformation__c)
                            ? di.npsp__FailureInformation__c
                            : 'BDI did not complete import (status: ' + di.npsp__Status__c + ')';
                    } else {
                        ir.errorMessage = 'Processed Data Import record not found';
                    }
                }
            }

            results.add(ir);
        }

        return results;
    }

    // ─── Private helpers ────────────────────────────────────────────────────

    private static String buildInsertErrorMessage(Database.SaveResult sr) {
        List<String> msgs = new List<String>();
        for (Database.Error err : sr.getErrors()) {
            msgs.add(err.getMessage());
        }
        return String.join(msgs, '; ');
    }
}
```

**Root cause of the failure:** `new List<SObject>(n)` in Apex creates a list **pre-filled with `n` null entries**, not an empty list with capacity `n`. My `diRecords.add(di)` then appended valid records *after* those nulls, so `Database.insert(diRecords, false)` saw null at position 0. The fix is to start with a truly empty list (`new List<SObject>()`) and simply `.add()` into it.

