    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {

        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Gather distinct Opportunity Ids
        Set<Id> oppIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            oppIds.add(req.opportunityId);
        }

        // SOQL 1: Opportunities
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // SOQL 2: Existing OpportunityContactRoles on those opps
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
        ];

        // SOQL 3: Existing Partial Soft Credits on those opps
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c,
                   npsp__Amount__c, npsp__Role_Name__c,
                   npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
        ];

        // ── VALIDATE THE WHOLE BATCH before any DML ──────────────────────
        for (SoftCreditRequest req : requests) {
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException(
                    'Partial soft credit amount must be a positive number.'
                );
            }

            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity ' + String.valueOf(req.opportunityId) + ' not found.'
                );
            }

            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Partial soft credit amount exceeds the opportunity amount.'
                );
            }

            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'A partial soft credit cannot be awarded to the primary contact.'
                );
            }
        }

        // ── Index existing OCRs by (OppId|ContactId) ─────────────────────
        Map<String, Integer> ocrFirstIdx = new Map<String, Integer>();
        List<OpportunityContactRole> ocrList = new List<OpportunityContactRole>();
        ocrList.addAll(existingOcrs);

        for (Integer i = 0; i < ocrList.size(); i++) {
            OpportunityContactRole ocr = ocrList[i];
            String key = String.valueOf(ocr.OpportunityId) + '|' + String.valueOf(ocr.ContactId);
            if (!ocrFirstIdx.containsKey(key)) {
                ocrFirstIdx.put(key, i);
            }
        }

        // ── Index existing PSCs by (OppId|ContactId) ─────────────────────
        Map<String, Integer> pscFirstIdx = new Map<String, Integer>();
        List<npsp__Partial_Soft_Credit__c> pscList = new List<npsp__Partial_Soft_Credit__c>();
        pscList.addAll(existingPscs);

        for (Integer i = 0; i < pscList.size(); i++) {
            npsp__Partial_Soft_Credit__c psc = pscList[i];
            String key = String.valueOf(psc.npsp__Opportunity__c) + '|' + String.valueOf(psc.npsp__Contact__c);
            if (!pscFirstIdx.containsKey(key)) {
                pscFirstIdx.put(key, i);
            }
        }

        // ── Build OCR DML lists ──────────────────────────────────────────
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();
        // Track the OCR (with resolved Id after DML) for each request
        List<OpportunityContactRole> ocrForRequest = new List<OpportunityContactRole>();
        // Track which ocrsToUpsert indices correspond to new (insert) records
        List<Boolean> ocrIsNew = new List<Boolean>();

        for (SoftCreditRequest req : requests) {
            String key = String.valueOf(req.opportunityId) + '|' + String.valueOf(req.contactId);

            if (ocrFirstIdx.containsKey(key)) {
                Integer idx = ocrFirstIdx.get(key);
                OpportunityContactRole keep = ocrList[idx];
                keep.Role = req.role;
                ocrsToUpsert.add(keep);
                ocrIsNew.add(false);
                ocrForRequest.add(keep);

                // Mark all other OCRs for same pair for deletion
                // Find them in the original list
                for (Integer i = 0; i < ocrList.size(); i++) {
                    if (i == idx) continue;
                    OpportunityContactRole other = ocrList[i];
                    String otherKey = String.valueOf(other.OpportunityId) + '|' + String.valueOf(other.ContactId);
                    if (otherKey == key && !ocrsToDelete.contains(other)) {
                        ocrsToDelete.add(other);
                    }
                }
            } else {
                OpportunityContactRole newOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId     = req.contactId,
                    Role          = req.role
                );
                ocrsToUpsert.add(newOcr);
                ocrIsNew.add(true);
                ocrForRequest.add(newOcr);
            }
        }

        // ── DML 1: upsert OCRs ───────────────────────────────────────────
        if (!ocrsToUpsert.isEmpty()) {
            upsert ocrsToUpsert;
        }

        // ── DML 2: delete duplicate OCRs ─────────────────────────────────
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // After upsert, all records in ocrForRequest now have Ids

        // ── Build PSC DML lists ──────────────────────────────────────────
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToDelete = new List<npsp__Partial_Soft_Credit__c>();

        for (Integer i = 0; i < requests.size(); i++) {
            SoftCreditRequest req = requests[i];
            OpportunityContactRole ocr = ocrForRequest[i];

            String key = String.valueOf(req.opportunityId) + '|' + String.valueOf(req.contactId);

            if (pscFirstIdx.containsKey(key)) {
                Integer idx = pscFirstIdx.get(key);
                npsp__Partial_Soft_Credit__c keep = pscList[idx];
                keep.npsp__Amount__c         = req.amount;
                keep.npsp__Role_Name__c      = req.role;
                keep.npsp__Contact_Role_ID__c = ocr.Id;
                pscsToUpsert.add(keep);

                // Mark all other PSCs for same pair for deletion
                for (Integer j = 0; j < pscList.size(); j++) {
                    if (j == idx) continue;
                    npsp__Partial_Soft_Credit__c other = pscList[j];
                    String otherKey = String.valueOf(other.npsp__Opportunity__c) + '|' + String.valueOf(other.npsp__Contact__c);
                    if (otherKey == key && !pscsToDelete.contains(other)) {
                        pscsToDelete.add(other);
                    }
                }
            } else {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c    = req.opportunityId,
                    npsp__Contact__c        = req.contactId,
                    npsp__Amount__c         = req.amount,
                    npsp__Role_Name__c      = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                );
                pscsToUpsert.add(newPsc);
            }
        }

        // ── DML 3: upsert PSCs ───────────────────────────────────────────
        if (!pscsToUpsert.isEmpty()) {
            upsert pscsToUpsert;
        }

        // ── DML 4: delete duplicate PSCs ─────────────────────────────────
        if (!pscsToDelete.isEmpty()) {
