/**
 * Turns a pledge (open Opportunity) into a monthly installment plan
 * by replacing its unpaid, non-written-off payments with a new schedule.
 */
public with sharing class PaymentPlanService {

    public class PaymentPlanException extends Exception {}

    /**
     * Replaces open payments on the given Opportunity with a new
     * installment schedule.
     *
     * @param opportunityId   Id of the pledge Opportunity
     * @param numberOfPayments number of installments (>= 1)
     * @param firstPaymentDate date of the first installment
     * @return the newly inserted payments in schedule order
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(
        Id opportunityId,
        Integer numberOfPayments,
        Date firstPaymentDate
    ) {

        // ── Guard: numberOfPayments ──────────────────────────────────────
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException(
                'numberOfPayments must be at least 1.'
            );
        }

        // ── Retrieve the Opportunity together with its payments ──────────
        // FOR UPDATE serialises concurrent edits on this pledge.
        List<Opportunity> oppList = [
            SELECT Id, Amount, IsClosed,
                (SELECT Id,
                        npe01__Payment_Amount__c,
                        npe01__Paid__c,
                        npe01__Written_Off__c
                 FROM npe01__OppPayment__r)
            FROM Opportunity
            WHERE Id = :opportunityId
            FOR UPDATE
        ];

        if (oppList.isEmpty()) {
            throw new PaymentPlanException(
                'Opportunity ' + opportunityId + ' not found.'
            );
        }

        Opportunity opp = oppList[0];

        // ── Guard: Opportunity must be open ──────────────────────────────
        if (opp.IsClosed) {
            throw new PaymentPlanException(
                'Opportunity ' + opp.Id + ' is closed; cannot schedule installments.'
            );
        }

        // ── Classify existing payments ───────────────────────────────────
        Decimal historyTotal = 0;
        List<npe01__OppPayment__c> paymentsToDelete = new List<npe01__OppPayment__c>();

        for (npe01__OppPayment__c p : opp.npe01__OppPayment__r) {
            if (p.npe01__Paid__c || p.npe01__Written_Off__c) {
                historyTotal += (p.npe01__Payment_Amount__c != null)
                                ? p.npe01__Payment_Amount__c
                                : 0;
            } else {
                paymentsToDelete.add(p);
            }
        }

        // ── Outstanding balance ──────────────────────────────────────────
        Decimal amount = (opp.Amount != null) ? opp.Amount : 0;
        Decimal outstanding = amount - historyTotal;

        // ── Guard: outstanding must be > 0 ───────────────────────────────
        if (outstanding <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount is not greater than zero.'
            );
        }

        // ── Delete the old open payments ─────────────────────────────────
        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }

        // ── Compute installment amounts ──────────────────────────────────
        Decimal perPayment = outstanding.divide(
            numberOfPayments,
            2,
            System.RoundingMode.DOWN
        );
        Decimal lastPaymentAmount = outstanding
                                    - (perPayment * (numberOfPayments - 1));

        // ── Build the new payment records ────────────────────────────────
        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>(
            numberOfPayments
        );

        for (Integer i = 0; i < numberOfPayments; i++) {
            newPayments.add(new npe01__OppPayment__c(
                npe01__Opportunity__c    = opportunityId,
                npe01__Payment_Amount__c = (i < numberOfPayments - 1)
                                            ? perPayment
                                            : lastPaymentAmount,
                npe01__Scheduled_Date__c = firstPaymentDate.addMonths(i),
                npe01__Paid__c           = false,
                npe01__Written_Off__c    = false
            ));
        }

        // ── Insert (order is preserved → schedule order) ─────────────────
        insert newPayments;

        return newPayments;
    }
}
