```apex
/**
 * FamilyService
 *
 * Links child contacts to parent contacts in NPSP Relationships.
 * With the org's default "List Setting" reciprocal method, creating the
 * Child→Parent (Type=Parent) record causes NPSP's trigger to automatically
 * create the reciprocal Parent→Child record using the Relationship Lookup
 * (Male=Son, Female=Daughter, Neutral=Child).
 *
 * Constraints satisfied:
 *   • 200 pairs → 1 SOQL, 1 DML (of our own).
 *   • Idempotent: skips any pair that already has a relationship in either direction.
 *   • Null / empty input is a no-op.
 */
public class FamilyService {

    public static void linkParents(Map<Id, Id> parentIdByChildId) {

        // ---- guard clause ----
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        // ---- collect every contact Id involved ----
        Set<Id> allContactIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            if (childId == null) continue;
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) continue;
            allContactIds.add(childId);
            allContactIds.add(parentId);
        }

        if (allContactIds.isEmpty()) {
            return;
        }

        // ---- 1 SOQL: any existing relationship touching these contacts ----
        List<npe4__Relationship__c> existingRels = [
            SELECT npe4__Contact__c, npe4__RelatedContact__c
            FROM npe4__Relationship__c
            WHERE npe4__Contact__c IN :allContactIds
               OR npe4__RelatedContact__c IN :allContactIds
        ];

        // Build a lookup of pairs that already exist (both directions)
        Set<String> existingPairKeys = new Set<String>();
        for (npe4__Relationship__c r : existingRels) {
            existingPairKeys.add(r.npe4__Contact__c + '|' + r.npe4__RelatedContact__c);
        }

        // ---- build the list to insert (1 record per pair; NPSP creates the reciprocal) ----
        List<npe4__Relationship__c> toInsert = new List<npe4__Relationship__c>();
        Set<String> newPairKeys = new Set<String>();

        for (Id childId : parentIdByChildId.keySet()) {
            if (childId == null) continue;
            Id parentId = parentIdByChildId.get(childId);
            if (parentId == null) continue;

            String keyChildToParent = childId + '|' + parentId;
            String keyParentToChild = parentId + '|' + childId;

            // Skip if a relationship already exists between this pair (either direction)
            if (existingPairKeys.contains(keyChildToParent)
             || existingPairKeys.contains(keyParentToChild)) {
                continue;
            }

            // Skip if we already queued this same pair within this call
            if (newPairKeys.contains(keyChildToParent)
             || newPairKeys.contains(keyParentToChild)) {
                continue;
            }

            npe4__Relationship__c rel = new npe4__Relationship__c();
            rel.npe4__Contact__c        = childId;
            rel.npe4__RelatedContact__c = parentId;
            rel.npe4__Type__c          = 'Parent';
            rel.npe4__Status__c        = 'Current';
            // ReciprocalRelationship left as org default ("List Setting") so NPSP
            // trigger auto-creates the Son/Daughter/Child reciprocal.

            toInsert.add(rel);
            newPairKeys.add(keyChildToParent);
        }

        // ---- 1 DML ----
        if (!toInsert.isEmpty()) {
            insert toInsert;
        }
    }
}
