/**
 * NPSP TDTM handler that creates a follow-up Task for major gifts (Closed Won, Amount >= 5000).
 *
 * Register in NPSP Settings > Trigger Configuration:
 *   Class:            OPP_MajorGiftFollowUp_TDTM
 *   Object:           Opportunity
 *   Trigger Action:   AfterInsert;AfterUpdate
 *   Load Order:       5
 *   Asynchronous:     unchecked
 */
public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    private static final Decimal AMOUNT_THRESHOLD = 5000;
    private static final String  STAGE_CLOSED_WON = 'Closed Won';

    public override DmlWrapper run(
            List<SObject> newlist,
            List<SObject> oldlist,
            Action triggerAction,
            Schema.DescribeSObjectResult objResult) {

        List<Task> tasksToInsert = new List<Task>();

        if (triggerAction == Action.AfterInsert) {

            // Qualify: the record is created already Closed Won with Amount >= 5000
            for (SObject sobj : newlist) {
                Opportunity opp = (Opportunity) sobj;
                if (isQualified(opp)) {
                    tasksToInsert.add(buildTask(opp));
                }
            }

        } else if (triggerAction == Action.AfterUpdate) {

            // Qualify: the record *becomes* Closed Won + Amount >= 5000
            // (was not both before) so editing an already-qualified gift is a no-op.
            Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(
                (List<Opportunity>) oldlist
            );

            for (SObject sobj : newlist) {
                Opportunity newOpp = (Opportunity) sobj;

                if (!isQualified(newOpp)) {
                    continue;
                }

                Opportunity oldOpp = oldMap.get(newOpp.Id);
                if (oldOpp != null && !isQualified(oldOpp)) {
                    tasksToInsert.add(buildTask(newOpp));
                }
            }
        }

        // Perform 1 DML statement of our own (bulk-safe)
        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }

        // Return an empty DmlWrapper so the dispatcher does not attempt another insert.
        DmlWrapper wrapper = new DmlWrapper();
        wrapper.objectsToInsert = new List<SObject>();
        wrapper.objectsToUpdate = new List<SObject>();
        wrapper.objectsToDelete = new List<SObject>();
        return wrapper;
    }

    // ── private helpers ──────────────────────────────────────────────────────

    private static Boolean isQualified(Opportunity opp) {
        return opp.StageName == STAGE_CLOSED_WON
            && opp.Amount != null
            && opp.Amount >= AMOUNT_THRESHOLD;
    }

    private static Task buildTask(Opportunity opp) {
        Task t = new Task();
        t.Subject      = 'Major gift thank-you call';
        t.Priority     = 'High';
        t.Status       = 'Not Started';
        t.WhatId       = opp.Id;
        t.WhoId        = opp.npsp__Primary_Contact__c;   // may be null
        t.OwnerId      = opp.OwnerId;
        t.ActivityDate = opp.CloseDate != null ? opp.CloseDate.addDays(3) : null;
        return t;
    }
}
