public with sharing class RecordAccessService {
    private static final Integer SOQL_BATCH_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id currentUserId = UserInfo.getUserId();
        if (currentUserId == null) {
            return editable;
        }

        // Convert set to list for deterministic iteration; ignore null IDs.
        List<Id> inputIds = new List<Id>();
        for (Id recordId : recordIds) {
            if (recordId != null) {
                inputIds.add(recordId);
            }
        }

        Integer startIdx = 0;
        Integer totalCount = inputIds.size();

        while (startIdx < totalCount) {
            Integer stopIdx = startIdx + SOQL_BATCH_SIZE;
            if (stopIdx > totalCount) {
                stopIdx = totalCount;
            }

            // Build the batch manually since Apex has no subList method.
            List<Id> batch = new List<Id>();
            for (Integer i = startIdx; i < stopIdx; i++) {
                batch.add(inputIds[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :currentUserId
                  AND RecordId IN :batch
            ]) {
                if (access.HasEditAccess) {
                    editable.add(access.RecordId);
                }
            }

            startIdx = stopIdx;
        }

        return editable;
    }
}
