```apex
public with sharing class AccountOwnershipService {

    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        // Bypass all Account trigger actions for this ownership change
        TriggerBase.bypass('Account');
        try {
            // Build Account records to update — no SOQL needed
            List<Account> accounts = new List<Account>();
            for (Id accId : accountIds) {
                accounts.add(new Account(Id = accId, OwnerId = newOwnerId));
            }

            // Query Contacts under these Accounts — 1 SOQL query
            List<Contact> contacts = [
                SELECT Id FROM Contact WHERE AccountId IN :accountIds
            ];
            for (Contact c : contacts) {
                c.OwnerId = newOwnerId;
            }

            // All-or-none DML via update keyword; exceptions propagate to caller.
            // If the second update throws, the unhandled exception rolls back the
            // entire transaction (including the first update) unless the caller
            // catches and commits. This satisfies "all-or-none DML" with only
            // two DML statements total.
            update accounts;   // DML 1 — Account triggers are bypassed
            update contacts;   // DML 2 — Contact triggers/actions run normally
        } finally {
            // Whether success or failure, restore normal Account automation
            TriggerBase.clearBypass('Account');
        }
    }
}
