    @IsTest
    static void testDecreaseMoreThanHalfIsRejected() {
        Id fakeId = TriggerTestUtility.getFakeId(Opportunity.SObjectType);

        Opportunity oldRec = new Opportunity(Id = fakeId, Amount = 1000);
        Opportunity newRec = new Opportunity(Id = fakeId, Amount = 499);

        List<Opportunity> triggerNew = new List<Opportunity>{ newRec };
        List<Opportunity> triggerOld = new List<Opportunity>{ oldRec };

        TA_Opportunity_GuardAmountDecrease action = new TA_Opportunity_GuardAmountDecrease();
        action.beforeUpdate(triggerNew, triggerOld);

        System.assert(newRec.hasErrors(), 'Expected the record to have a validation error');
        List<Database.Error> errors = newRec.getErrors();
        System.assertEquals(1, errors.size(), 'Expected exactly one error');
        System.assertEquals(
            TA_Opportunity_GuardAmountDecrease.ERROR_MESSAGE,
            errors[0].getMessage(),
            'Error message mismatch'
        );
    }

    // ---------------------------------------------------------------------------
    // (b) Reduction of exactly half (1000 -> 500) is accepted (no error).
    // (c) An increase (1000 -> 2000) is accepted.
    // (d) A record whose previous Amount was null is accepted without exception.
    // ---------------------------------------------------------------------------
    @IsTest
