public inherited sharing class TA_Case_RollupOpenCount
        implements TriggerAction.AfterInsert,
                   TriggerAction.AfterUpdate,
                   TriggerAction.AfterDelete,
                   TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        recalculate(triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        recalculate(triggerNew, triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        recalculate(null, triggerOld);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        recalculate(triggerNew, null);
    }

    private void recalculate(List<SObject> newRecords, List<SObject> oldRecords) {
        Set<Id> accountIds = new Set<Id>();

        if (newRecords != null) {
            for (SObject s : newRecords) {
                Id accId = (Id) s.get('AccountId');
                if (accId != null) {
                    accountIds.add(accId);
                }
            }
        }

        if (oldRecords != null) {
            for (SObject s : oldRecords) {
                Id accId = (Id) s.get('AccountId');
                if (accId != null) {
                    accountIds.add(accId);
                }
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // 1 SOQL: aggregate count of open cases per affected account
        Map<Id, Integer> openCountByAccount = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            openCountByAccount.put(
                (Id) ar.get('AccountId'),
                (Integer) ar.get('cnt')
            );
        }

        // 1 DML: set the count on every affected account (0 if no open cases remain)
        List<Account> accountsToSet = new List<Account>();
        for (Id accId : accountIds) {
            Integer count = 0;
            if (openCountByAccount.containsKey(accId)) {
                count = openCountByAccount.get(accId);
            }
            accountsToSet.add(new Account(
                Id = accId,
                FB_Open_Case_Count__c = count
            ));
        }

        update accountsToSet;
    }
}
